class Room {
    constructor(data, imvu) {
      this.id = data.id || null;
      this.name = data.name || null;
      this.description = data.description || null;
      this.type = data.type || null;
      this.privacy = data.privacy || null;
      this.auto_boot_when_owner_leaves = data.auto_boot_when_owner_leaves || null;
      this.auto_boot_timeout = data.auto_boot_timeout || null;
      this.image_url = data.image_url || null;
      this.themed_image_url = data.themed_image_url || null;
      this.occupancy = data.occupancy || null;
      this.capacity = data.capacity || null;
      this.language = data.language || null;
      this.language_code = data.language_code || null;
      this.rating = data.rating || null;
      this.content_rating = data.content_rating || null;
      this.owner_avatarname = data.owner_avatarname || null;
      this.vip_only = data.vip_only || null;
      this.is_ap = data.is_ap || null;
      this.is_vip = data.is_vip || null;
      this.is_age_verified = data.is_age_verified || null;
      this.is_friends_only = data.is_friends_only || null;
      this.is_non_guest_only = data.is_non_guest_only || null;
      this.total_credits_tipped = data.total_credits_tipped || null;
      this.has_plus_badge = data.has_plus_badge || null;
      this.is_plus_badge_compatible = data.is_plus_badge_compatible || null;
      this.has_audio = data.has_audio || null;
      this.supports_youtube = data.supports_youtube || null;
      this.supports_audience = data.supports_audience || null;
      this.mimic_chat_room = data.mimic_chat_room || null;
      this.rendered_image = data.rendered_image || null;
      this.join_room_url = data.join_room_url || null;
      this.customers_id = data.customers_id || null;
      this.customers_room_id = data.customers_room_id || null;
      this.is_expired = data.is_expired || null;
  
      this.users = imvu.users;
      this.furnitures = imvu.furnitures;
      this.imvu = imvu;
    }

  }
  
  module.exports = Room;
  